     * Encode a character for URLs.
     *
     * <p>This method now performs defensive null checks and respects an optional list of
     * {@code immune} characters that should not be encoded.  The original implementation
     * ignored the {@code immune} parameter and could throw a {@link NullPointerException}
     * if {@code c} was {@code null}.  The updated version validates inputs, uses
     * immutable data structures, and guarantees that the returned string is a valid
     * percent‑encoded representation suitable for inclusion in a URL.</p>
     *
     * @param immune characters that should be left unencoded; may be {@code null}
     * @param c      the character to encode; must not be {@code null}
     * @return the percent‑encoded string representing {@code c}
     * @throws IllegalArgumentException if {@code c} is {@code null}
     */
    public String encodeCharacter(char[] immune, Character c) {
        if (c == null) {
            throw new IllegalArgumentException("Character to encode cannot be null");
        }

        final char ch = c.charValue();

        // If the character is explicitly immune, return it unchanged
        if (immune != null) {
            for (char immuneChar : immune) {
                if (immuneChar == ch) {
                    return String.valueOf(ch);
                }
            }
        }

        // Characters that are always safe to leave unencoded
        if (UNENCODED_SET.contains(ch)) {
            return String.valueOf(ch);
        }

        final String cStr = String.valueOf(ch);
        final byte[] bytes = toUtf8Bytes(cStr);
        final StringBuilder sb = new StringBuilder(bytes.length * 3);

        for (byte b : bytes) {
            appendTwoUpperHex(sb.append('%'), b);
        }
        return sb.toString();
    }

    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        // Implementation retained from original source – safe and efficient
        sb.append(Character.forDigit((b >> 4) & 0xF, 16).toUpperCase());
        sb.append(Character.forDigit(b & 0xF, 16).toUpperCase());
        return sb;
    }

    private static byte[] toUtf8Bytes(String str) {
        // Implementation retained from original source – safe and efficient
        try {
            return str.getBytes("UTF-8");
        } catch (java.io.UnsupportedEncodingException e) {
            // UTF-8 is guaranteed to be supported; rethrow as unchecked
            throw new RuntimeException(e);
        }
    }

