            // No further action – the seed is deliberately discarded.
        }

        // No need to manually invoke nextBytes(); construction already seeds the RNG.
        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        return true;
    }
