/**
 * Decodes a JWT string into a {@link JWT} object while enforcing strict algorithm validation.
 */
public class JWTDecoder {

    /* --------------------------------------------------------------------- *
     *  Algorithm whitelist – only these algorithms are considered safe.      *
     * --------------------------------------------------------------------- */
    private static final Set<String> ALLOWED_ALGORITHMS =
            Collections.unmodifiableSet(new HashSet<String>() {{
                add("HS256");
                add("HS384");
                add("HS512");
                add("RS256");
                add("RS384");
                add("RS512");
                add("ES256");
                add("ES384");
                add("ES512");
            }});

    /* --------------------------------------------------------------------- *
     *  Core decoding logic.                                                 *
     * --------------------------------------------------------------------- */
    private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {

        /* Validate the number of parts – a JWT must contain exactly 2 or 3 parts. */
        if (parts == null || parts.length < 2 || parts.length > 3) {
            throw new IllegalArgumentException("Invalid JWT format: expected 2 or 3 parts");
        }

        /* ------------------------------------------------------------------ *
         *  Algorithm validation                                               *
         * ------------------------------------------------------------------ */
        if (header == null || header.algorithm == null) {
            throw new InvalidJWTSignatureException("Missing JWT header or algorithm");
        }

        String algName = header.algorithm.getName();
        if (algName == null || algName.trim().isEmpty()) {
            throw new InvalidJWTSignatureException("Algorithm name is missing or empty");
        }

        /* Reject unsigned tokens (algorithm 'none') */
        if ("none".equalsIgnoreCase(algName)) {
            throw new InvalidJWTSignatureException("Unsigned JWTs (alg='none') are not allowed");
        }

        /* Enforce whitelist of supported algorithms */
        if (!ALLOWED_ALGORITHMS.contains(algName)) {
            throw new InvalidJWTSignatureException("Unsupported JWT algorithm: " + algName);
        }

        /* ------------------------------------------------------------------ *
         *  Signature handling                                                *
         * ------------------------------------------------------------------ */
        int index = encodedJWT.lastIndexOf(".");
        if (index == -1) {
            throw new IllegalArgumentException("Malformed JWT: missing '.' separator");
        }

        /* The message comprises the first two segments of the entire JWT. */
        byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

        /* If a signature is present, a verifier must be supplied. */
        if (parts.length == 3 && verifier == null) {
            throw new MissingVerifierException(
                    "No Verifier has been provided for verifying a signature signed using [" + algName + "]"
            );
        }

        /* If a signature is absent but a verifier is supplied, treat as invalid. */
        if (parts.length == 2 && verifier != null) {
            throw new InvalidJWTSignatureException("Signature missing but verifier provided");
        }

        /* Verify the signature when present. */
        if (parts.length == 3) {
            byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
            verifier.verify(header.algorithm, message, signature);
        }

        /* ------------------------------------------------------------------ *
         *  Payload deserialization                                           *
         * ------------------------------------------------------------------ */
        byte[] payloadBytes = base64Decode(parts[1].getBytes(StandardCharsets.UTF_8));
        JWT jwt = Mapper.deserialize(payloadBytes, JWT.class);

        /* ------------------------------------------------------------------ *
         *  Claim validation                                                  *
         * ------------------------------------------------------------------ */
        if (jwt.isExpired()) {
            throw new JWTExpiredException();
        }

        if (jwt.isUnavailableForProcessing()) {
            throw new JWTUnavailableForProcessingException();
        }

        return jwt;
    }

    /* --------------------------------------------------------------------- *
     *  Base64 decoding helper                                             *
     * --------------------------------------------------------------------- */
    private byte[] base64Decode(byte[] bytes) {
        // Implementation omitted – assumed to be safe and correctly handle padding.
        // In production, use java.util.Base64.getUrlDecoder().
