public class Expander {

    // other methods

    /**
     * Extracts all readable entries from the supplied {@link ArchiveEntrySupplier} into the
     * specified {@code targetDirectory}. The method performs rigorous path validation to
     * prevent path‑traversal attacks and ensures that no files are written outside the
     * intended extraction root.
