     * @param writer          helper that writes entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which entries should be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("Encountered entry with empty name");
            }
            // Reject absolute paths or paths that start with a separator.
            if (Paths.get(entryName).isAbsolute()
                    || entryName.startsWith("/") || entryName.startsWith("\\")
                    || entryName.contains("..")) {
                throw new IOException("Invalid entry name (potential path traversal): "
                        + entryName);
            }

            // Resolve the entry against the target directory and normalize the path.
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException("Expanding " + entryName
                        + " would create file outside of " + targetDirectory);
            }

            // Handle directories.
            if (nextEntry.isDirectory()) {
                Files.createDirectories(entryPath);
            } else {
                // Ensure parent directories exist.
                Path parent = entryPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
