/**
 * Utility class that determines whether a self‑update request is allowed.
 *
 * <p>The original implementation performed only superficial checks on the
 * {@link ScimUser} payload.  It did not verify that the caller was actually
 * the owner of the account being updated, which could allow an attacker to
 * change another user’s email address.  The patched version now enforces
 * strict ownership checks and validates that email changes are only
 * accepted when the new address has not yet been verified.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is permitted to update the
     * specified user.  The method performs the following checks:
     * <ul>
     *   <li>Extracts the target user ID from the request URL.</li>
     *   <li>Retrieves the authenticated user ID from the request context.</li>
     *   <li>Ensures the authenticated user ID matches the target user ID.</li>
     *   <li>Validates that the payload contains the same user ID.</li>
     *   <li>If the primary email is being changed, the new address must not
     *       already be verified.</li>
     *   <li>All other fields are compared for equality.</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Extract the target user ID from the URL path
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        if (id == null || id.isEmpty()) {
            return false; // malformed request
        }

        // 2. Retrieve the authenticated user ID from the request context
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (authenticatedUserId == null || !authenticatedUserId.equals(id)) {
            return false; // caller is not the owner of the account
        }

        // 3. Parse the request body into a ScimUser object
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        if (scimUserFromRequest == null) {
            return false; // invalid payload
        }

        // 4. Verify that the payload references the same user ID
        if (!id.equals(scimUserFromRequest.getId())) {
            return false;
        }

        // 5. Retrieve the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 6. Perform field‑by‑field comparison
        if (!safeEquals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change is only allowed if the new address is not yet verified
            if (scimUserFromRequest.isVerified()) {
                return false;
            }
        }

        if (!safeEquals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }

        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        if (!safeEquals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Retrieves the authenticated user ID from the request.  The method first
     * looks for a request attribute named {@code authenticatedUserId}.  If
     * absent, it falls back to the {@code X-Authenticated-User} header.
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if none is found
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Object attr = request.getAttribute("authenticatedUserId");
        if (attr instanceof String) {
            return (String) attr;
        }
        return request.getHeader("X-Authenticated-User");
    }

    /**
     * Safely compares two strings, handling {@code null} values.
     *
     * @param a first string
     * @param b second string
     * @return {@code true} if both are equal or both are {@code null}
     */
    private boolean safeEquals(String a, String b) {
        return (a == null) ? (b == null) : a.equals(b);
    }
}
